package contractcancellation

import (
	"context"
	"errors"
	"fmt"

	"github.com/parstis/bnpl-backend/pkg/core/model"
)

// ErrNotSupported indicates the configured adapter cannot perform a real
// Financial Core cancellation request. Callers must not treat this as success.
var ErrNotSupported = errors.New("contract cancellation financial request is not supported")

var (
	// ErrRetryableFailure marks a transport-neutral failure that is safe to
	// retry with the same idempotency identity.
	ErrRetryableFailure = errors.New("contract cancellation retryable failure")

	// ErrPermanentFailure marks a definitive failure for which repeating the
	// same request is not expected to succeed.
	ErrPermanentFailure = errors.New("contract cancellation permanent failure")

	// ErrAmbiguousFailure marks a failure where the external outcome cannot be
	// determined safely and explicit reconciliation is required.
	ErrAmbiguousFailure = errors.New("contract cancellation ambiguous failure")
)

// Retryable wraps err with transport-neutral retry semantics. Adapters should
// use this for timeouts, temporary unavailability, and equivalent failures
// when replaying the same idempotent request is safe.
func Retryable(err error) error {
	const op = "contractcancellation.Retryable"

	if err == nil {
		return nil
	}

	return fmt.Errorf("%s: %w: %w", op, ErrRetryableFailure, err)
}

// Permanent wraps err with transport-neutral permanent-failure semantics.
func Permanent(err error) error {
	const op = "contractcancellation.Permanent"

	if err == nil {
		return nil
	}

	return fmt.Errorf("%s: %w: %w", op, ErrPermanentFailure, err)
}

// Ambiguous wraps err when the external outcome cannot be determined safely.
func Ambiguous(err error) error {
	const op = "contractcancellation.Ambiguous"

	if err == nil {
		return nil
	}

	return fmt.Errorf("%s: %w: %w", op, ErrAmbiguousFailure, err)
}

// RequestCancellationInput carries transport-neutral cancellation request inputs.
//
// IdempotencyKey is the stable Financial Core correlation identity generated by
// BNPL for this cancellation process. Retries MUST reuse the same key.
type RequestCancellationInput struct {
	// IdempotencyKey is the stable Financial Core correlation identity for this cancellation.
	IdempotencyKey string

	// TenantID identifies the Financial Core tenant for the request.
	TenantID string
	// ContextID identifies the Financial Core request context for the request.
	ContextID string

	// ContractID is the BNPL contract being cancelled.
	ContractID model.ContractID
	// CustomerID is the internal BNPL customer primary key for the contract.
	CustomerID model.CustomerID

	// Reason is the business reason for requesting cancellation.
	Reason model.ContractCancellationReason
}

// RequestCancellationResult carries the authoritative synchronous result of a
// Financial Core cancellation command.
//
// Accepted means Financial Core completed and durably accepted the requested
// cancellation operation. Retries with the same idempotency key may return the
// same authoritative result with ReusedIdempotentResult set.
type RequestCancellationResult struct {
	// Accepted reports that Financial Core durably accepted the cancellation.
	Accepted bool
	// ReusedIdempotentResult reports that Financial Core returned a prior idempotent result.
	ReusedIdempotentResult bool
}

// Client requests contract cancellation from Financial Core.
type Client interface {
	// RequestCancellation asks Financial Core to cancel the contract under the given idempotency key.
	RequestCancellation(
		ctx context.Context,
		input RequestCancellationInput,
	) (RequestCancellationResult, error)
}
